sp_widget.script:
(function() {
  try { data.chatbotWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {}); } catch(e) {}

    data.applications = [];

    data.stats = {

        total: 0,

        shortlisted: 0,

        assessment: 0,

        interview: 0,

        offers: 0

    };


    /*
     * =========================================================
     * STUDENT APPLICATION
     * =========================================================
     */

    var applicationGR = new GlideRecord(
        'x_snc_campus360_student_application'
    );

    applicationGR.orderByDesc('application_date');

    applicationGR.query();


    while (applicationGR.next()) {


        var student =
            applicationGR.getDisplayValue(
                'student_reference'
            ) || '';


        var studentId = '';

        if (applicationGR.student_reference) {

            studentId =
                applicationGR.student_reference
                .getRefRecord()
                .getDisplayValue('student_id');

        }


        var opportunity =
            applicationGR.getDisplayValue(
                'opportunity_reference'
            ) || '';


        var company = '';

        if (applicationGR.opportunity_reference) {

            var opportunityGR =
                applicationGR.opportunity_reference
                .getRefRecord();

            if (opportunityGR &&
                opportunityGR.isValidRecord()) {

                company =
                    opportunityGR.getDisplayValue(
                        'company_reference'
                    ) || '';

            }

        }


        var status =
            applicationGR.getDisplayValue(
                'application_status'
            ) ||
            applicationGR.getValue(
                'application_status'
            ) ||
            '';


        var assessment =
            applicationGR.getDisplayValue(
                'assessment_status'
            ) ||
            applicationGR.getValue(
                'assessment_status'
            ) ||
            '';


        var interview =
            applicationGR.getDisplayValue(
                'interview_status'
            ) ||
            applicationGR.getValue(
                'interview_status'
            ) ||
            '';


        var offer =
            applicationGR.getDisplayValue(
                'offer_status'
            ) ||
            applicationGR.getValue(
                'offer_status'
            ) ||
            '';


        var response =
            applicationGR.getDisplayValue(
                'student_response'
            ) ||
            applicationGR.getValue(
                'student_response'
            ) ||
            '';


        var appliedDate =
            applicationGR.getDisplayValue(
                'application_date'
            ) || '';


        /*
         * INITIALS
         */

        var initials = '';

        if (student) {

            var words =
                student.trim().split(/\s+/);

            if (words.length === 1) {

                initials =
                    words[0].substring(0, 2);

            } else {

                initials =
                    words[0].charAt(0) +
                    words[1].charAt(0);

            }

        }

        initials =
            initials.toUpperCase();


        /*
         * OPPORTUNITY ID
         */

        var opportunityId = '';

        if (applicationGR.opportunity_reference) {

            var oppRecord =
                applicationGR.opportunity_reference
                .getRefRecord();

            if (
                oppRecord &&
                oppRecord.isValidRecord()
            ) {

                opportunityId =
                    oppRecord.getValue(
                        'opportunity_id'
                    ) || '';

            }

        }


        /*
         * RECORD
         */

        data.applications.push({

            sys_id:
                applicationGR.getUniqueValue(),

            student:
                student,

            studentId:
                studentId,

            opportunity:
                opportunity,

            opportunityId:
                opportunityId,

            company:
                company,

            appliedDate:
                appliedDate,

            status:
                status,

            assessment:
                assessment,

            interview:
                interview,

            offer:
                offer,

            response:
                response,

            initials:
                initials

        });


        /*
         * =====================================================
         * STATS
         * =====================================================
         */

        data.stats.total++;


        if (status === 'Shortlisted') {

            data.stats.shortlisted++;

        }


        if (
            assessment === 'In Progress' ||
            assessment === 'Completed'
        ) {

            data.stats.assessment++;

        }


        if (
            interview === 'Scheduled' ||
            interview === 'Completed'
        ) {

            data.stats.interview++;

        }


        if (
            offer &&
            offer !== 'Not Offered' &&
            offer !== 'None'
        ) {

            data.stats.offers++;

        }

    }

})();

try {
  data.aiWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {});
  data.chatbotWidget = data.aiWidget;
} catch(e) {}
